'use strict';

// Copy helpers for the notification templates.
// pluralize() picks the plural form of a noun and formatCount() renders the
// "<n> <word>" phrase that the templates interpolate.

const IRREGULAR = {
  person: 'people',
  child: 'children',
  foot: 'feet',
  mouse: 'mice',
  analysis: 'analyses',
};

function pluralize(count, word) {
  if (count === 1) return word;
  return IRREGULAR[word] || word + 's';
}

function formatCount(count, word) {
  return String(count) + ' ' + pluralize(count, word);
}

module.exports = { pluralize, formatCount, IRREGULAR };

