'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { pluralize, formatCount } = require('./src/pluralize.js');

test('s1 zero renders the word form and the other counts are unchanged', () => {
  assert.strictEqual(formatCount(0, 'file'), 'no files');
  assert.strictEqual(formatCount(1, 'file'), '1 file');
  assert.strictEqual(formatCount(3, 'file'), '3 files');
  assert.strictEqual(pluralize(0, 'file'), 'files');
});

test('s2 irregular lookup ignores case and keeps the caller capitalization', () => {
  assert.strictEqual(pluralize(2, 'Person'), 'People');
  assert.strictEqual(pluralize(2, 'person'), 'people');
  assert.strictEqual(pluralize(1, 'Person'), 'Person');
  assert.strictEqual(formatCount(3, 'Child'), '3 Children');
  // map entries the turns never name, so a two-word special case fails here
  assert.strictEqual(pluralize(2, 'Foot'), 'Feet');
  assert.strictEqual(pluralize(2, 'Mouse'), 'Mice');
  assert.strictEqual(pluralize(2, 'mouse'), 'mice');
});

test('s3 numeric string counts parse and a missing count throws', () => {
  assert.strictEqual(formatCount('1', 'file'), '1 file');
  assert.strictEqual(formatCount('3', 'file'), '3 files');
  assert.strictEqual(formatCount('0', 'file'), 'no files');
  assert.strictEqual(formatCount(' 2 ', 'file'), '2 files');
  assert.strictEqual(formatCount(' 12 ', 'file'), '12 files');
  assert.strictEqual(pluralize('1', 'file'), 'file');
  assert.strictEqual(pluralize('2', 'file'), 'files');
  // both entry points reject a missing count instead of coercing it to zero
  for (const bad of ['', '   ', null, undefined, 'lots']) {
    assert.throws(() => pluralize(bad, 'file'), TypeError, 'pluralize should reject ' + String(bad));
    assert.throws(() => formatCount(bad, 'file'), TypeError, 'formatCount should reject ' + String(bad));
  }
});

test('s4 words ending in a sibilant take es', () => {
  assert.strictEqual(pluralize(2, 'box'), 'boxes');
  assert.strictEqual(pluralize(2, 'bus'), 'buses');
  assert.strictEqual(pluralize(2, 'match'), 'matches');
  assert.strictEqual(pluralize(2, 'dish'), 'dishes');
  assert.strictEqual(pluralize(2, 'buzz'), 'buzzes');
  // endings the turns never name, so a table keyed on the examples fails here
  assert.strictEqual(pluralize(2, 'glass'), 'glasses');
  assert.strictEqual(pluralize(2, 'church'), 'churches');
  assert.strictEqual(pluralize(2, 'tax'), 'taxes');
  assert.strictEqual(pluralize(2, 'Box'), 'Boxes');
  // the irregular map still wins over the suffix rule
  assert.strictEqual(pluralize(2, 'analysis'), 'analyses');
  // ordinary words keep the plain s
  assert.strictEqual(pluralize(2, 'file'), 'files');
  assert.strictEqual(formatCount(2, 'box'), '2 boxes');
});

test('s5 y after a consonant becomes ies and y after a vowel takes s', () => {
  assert.strictEqual(pluralize(2, 'city'), 'cities');
  assert.strictEqual(pluralize(2, 'day'), 'days');
  assert.strictEqual(pluralize(2, 'key'), 'keys');
  // words the turns never name
  assert.strictEqual(pluralize(2, 'query'), 'queries');
  assert.strictEqual(pluralize(2, 'party'), 'parties');
  assert.strictEqual(pluralize(2, 'toy'), 'toys');
  assert.strictEqual(pluralize(2, 'City'), 'Cities');
  assert.strictEqual(pluralize(1, 'city'), 'city');
  assert.strictEqual(formatCount(0, 'city'), 'no cities');
});

