'use strict';

// Copy helpers for the notification templates.
// pluralize() picks the plural form of a noun and formatCount() renders the
// "<n> <word>" phrase that the templates interpolate.

const IRREGULAR = {
  person: 'people',
  child: 'children',
  foot: 'feet',
  mouse: 'mice',
  analysis: 'analyses',
};

const ZERO_WORD = 'no';

// Counts reach the templates as numbers from code and as strings from the
// digest query. A missing count is not the same as a count of zero, so
// anything that is not a finite number is rejected rather than coerced.
function toCount(count) {
  if (typeof count === 'number' && Number.isFinite(count)) return count;
  if (typeof count === 'string' && count.trim() !== '') {
    const parsed = Number(count.trim());
    if (Number.isFinite(parsed)) return parsed;
  }
  throw new TypeError('count must be a number or a numeric string, got ' + String(count));
}

// Subject lines pass the noun capitalized, so an irregular form has to come
// back wearing the capitalization the caller used.
function matchCase(source, plural) {
  const first = String(source).charAt(0);
  if (first && first !== first.toLowerCase()) {
    return plural.charAt(0).toUpperCase() + plural.slice(1);
  }
  return plural;
}

function pluralize(count, word) {
  const n = toCount(count);
  if (n === 1) return word;
  const irregular = IRREGULAR[String(word).toLowerCase()];
  if (irregular) return matchCase(word, irregular);
  if (/(s|x|z|ch|sh)$/i.test(word)) return word + 'es';
  if (/[^aeiou]y$/i.test(word)) return word.slice(0, -1) + 'ies';
  return word + 's';
}

function formatCount(count, word) {
  const n = toCount(count);
  const shown = n === 0 ? ZERO_WORD : String(n);
  return shown + ' ' + pluralize(n, word);
}

module.exports = { pluralize, formatCount, IRREGULAR };

